<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8" />
<meta name="viewport" content="width=device-width, initial-scale=1.0" />
<title>Composition with Red, Blue and Yellow — Piet Mondrian, 1930</title>
<link rel="preconnect" href="https://fonts.googleapis.com" />
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
<link href="https://fonts.googleapis.com/css2?family=Archivo:wght@400;500;600;700;800;900&display=swap" rel="stylesheet" />
<style>
  :root {
    --red: #E4342B;
    --blue: #2B3BE4;
    --yellow: #F5C518;
    --black: #000000;
    --white: #FFFFFF;
  }
  * { box-sizing: border-box; }
  html, body { margin: 0; padding: 0; }
  body {
    background: var(--white);
    color: var(--black);
    font-family: 'Archivo', system-ui, -apple-system, sans-serif;
    -webkit-font-smoothing: antialiased;
    line-height: 1.5;
  }

  /* ---------- Hero ---------- */
  .hero {
    display: flex;
    flex-direction: column;
    align-items: center;
    padding: 48px 24px 40px;
  }
  .hero-stage {
    position: relative;
    width: min(70vw, 480px);
    aspect-ratio: 4 / 5;
    margin: 0 auto;
  }
  .hero-fallback { position: absolute; inset: 0; }
  #three-canvas {
    position: absolute; inset: 0;
    width: 100%; height: 100%;
    display: none;
    touch-action: none;
    cursor: grab;
  }
  #three-canvas:active { cursor: grabbing; }

  /* CSS composition (static fallback, also the visual language) */
  .comp { position: absolute; inset: 0; background: var(--white); }
  .line { position: absolute; background: var(--black); z-index: 2; }
  .line.v { width: 3%; height: 100%; top: 0; }
  .line.h { height: 3%; left: 0; width: 100%; }
  .block { position: absolute; z-index: 1; }
  .block.red { right: 0; top: 0; width: 40%; height: 32%; background: var(--red); }
  .block.blue { left: 0; bottom: 0; width: 24%; height: 19.2%; background: var(--blue); }
  .block.yellow { right: 0; bottom: 0; width: 40%; height: 16%; background: var(--yellow); }

  .hero h1 {
    margin: 30px 0 0;
    font-size: clamp(28px, 5vw, 54px);
    font-weight: 900;
    text-transform: uppercase;
    letter-spacing: -0.01em;
    text-align: center;
    line-height: 1.05;
    max-width: 820px;
  }
  .subtitle {
    margin: 14px 0 0;
    font-size: clamp(16px, 2.5vw, 22px);
    font-weight: 600;
    text-align: center;
  }
  .alt-title {
    margin: 6px 0 0;
    font-size: 14px;
    font-weight: 500;
    color: #4a4a4a;
    text-align: center;
  }

  /* ---------- Facts ---------- */
  .facts-section {
    max-width: 900px;
    margin: 48px auto 0;
    padding: 0 24px;
  }
  .facts {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 6px;
    background: var(--black);
    border: 6px solid var(--black);
  }
  .fact { background: var(--white); padding: 26px 24px; }
  .fact .label {
    display: block;
    font-size: 13px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    margin-bottom: 10px;
  }
  .fact p { margin: 0; font-size: 16px; line-height: 1.55; font-weight: 500; }
  .fact-yellow { background: var(--yellow); }
  .fact-blue { background: var(--blue); color: var(--white); }
  .fact-red { background: var(--red); color: var(--white); }

  /* ---------- Read more ---------- */
  .readmore {
    max-width: 900px;
    margin: 48px auto 64px;
    padding: 0 24px;
    text-align: center;
  }
  .readmore p {
    margin: 0 0 18px;
    font-size: 13px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.1em;
  }
  .readmore a {
    display: inline-block;
    background: var(--black);
    color: var(--white);
    text-decoration: none;
    padding: 16px 34px;
    font-size: 17px;
    font-weight: 700;
    transition: background 0.2s ease;
  }
  .readmore a:hover, .readmore a:focus-visible { background: var(--red); }

  @media (max-width: 640px) {
    .facts { grid-template-columns: 1fr; }
  }
</style>
</head>
